/**
 * A peer server. One websocket to the signaller carries every client, so
 * connections are addressed on it by id; each gets its own channel wrapper.
 *
 * A socket that drops is dialled again, and the registration reclaims the
 * session it left behind: same invite code, same clients still routed to
 * it. That is what lets a host whose laptop slept pick the call back up
 * instead of every guest having to build a new link. Until it is back,
 * `signallingAlive` is false and every channel knows it.
 *
 * A reclaim that fails - gone too long, signaller restarted - registers
 * fresh instead, under a new code. The clients that were attached to the
 * old session can no longer be reached, so their channels are stranded
 * rather than left to time out one signal at a time.
 */
export class PuterPeerServer extends EventTarget {
    constructor(peerConfig: any);
    connections: Map<any, any>;
    /** @type {string | undefined} */
    inviteCode: string | undefined;
    /**
     * @template {keyof PuterPeerServerEventMap} K
     * @overload
     * @param {K} type
     * @param {(this: PuterPeerServer, event: PuterPeerServerEventMap[K]) => void} listener
     * @param {boolean | AddEventListenerOptions} [options]
     * @returns {void}
     */
    addEventListener<K extends keyof PuterPeerServerEventMap>(type: K, listener: (this: PuterPeerServer, event: PuterPeerServerEventMap[K]) => void, options?: boolean | AddEventListenerOptions | undefined): void;
    /**
     * @overload
     * @param {string} type
     * @param {EventListenerOrEventListenerObject | null} listener
     * @param {boolean | AddEventListenerOptions} [options]
     * @returns {void}
     */
    addEventListener(type: string, listener: EventListenerOrEventListenerObject | null, options?: boolean | AddEventListenerOptions | undefined): void;
    /**
     * @template {keyof PuterPeerServerEventMap} K
     * @overload
     * @param {K} type
     * @param {(this: PuterPeerServer, event: PuterPeerServerEventMap[K]) => void} listener
     * @param {boolean | EventListenerOptions} [options]
     * @returns {void}
     */
    removeEventListener<K extends keyof PuterPeerServerEventMap>(type: K, listener: (this: PuterPeerServer, event: PuterPeerServerEventMap[K]) => void, options?: boolean | EventListenerOptions | undefined): void;
    /**
     * @overload
     * @param {string} type
     * @param {EventListenerOrEventListenerObject | null} listener
     * @param {boolean | EventListenerOptions} [options]
     * @returns {void}
     */
    removeEventListener(type: string, listener: EventListenerOrEventListenerObject | null, options?: boolean | EventListenerOptions | undefined): void;
    get signallingAlive(): boolean;
    /**
     * @param {PuterPeerOptions} [options]
     * @returns {Promise<string>}
     */
    start(options?: PuterPeerOptions): Promise<string>;
    /**
     * @param {Record<string, unknown>} envelope
     * @returns {boolean} whether the envelope left
     */
    relay(envelope: Record<string, unknown>): boolean;
    close(): void;
    #private;
}
export type PuterPeerOptions = import("./types.js").PuterPeerOptions;
export type PuterPeerServerEventMap = import("./events.js").PuterPeerServerEventMap;
